insert into public.notas_paroquia (paroquia_id, texto, fontes, confianca) values
  ('638baabc-f47e-5d9c-8015-bdd900b6e711', 'Vicariato Episcopal Urbano, 1ª Forania. Horários da matriz no cadastro da Cúria, confirmados pelo site da Catedral ("missas diárias às 12h e aos domingos às 10h"); os do Convento de Santo Antônio só pela Cúria. Fora do formato: Última sexta-feira do mês, 15h: Hora Santa e Unção dos Enfermos', '{"https://catedral.com.br/","https://www.arqrio.com.br/curia/ajaxExibeAtividadesLocal.php?id=2","https://www.arqrio.com.br/curia/ajaxExibeAtividadesLocal.php?id=284","https://www.arqrio.com.br/curia/ajaxParoquiasRecuperarDetalhes.php?id=2"}', 'alta'),
  ('cdf52587-11e2-5809-901b-9a7356084f5c', 'Vicariato Episcopal Urbano, 1ª Forania. Horários do cadastro da Cúria (sem data de atualização).', '{"https://www.arqrio.com.br/curia/ajaxExibeAtividadesLocal.php?id=41","https://www.arqrio.com.br/curia/ajaxParoquiasRecuperarDetalhes.php?id=41"}', 'media'),
  ('7b536c9a-73eb-5dea-93b6-3ad0efe96dae', 'Vicariato Episcopal Urbano, 4ª Forania. Horários do cadastro da Cúria (sem data de atualização).', '{"https://www.arqrio.com.br/curia/ajaxExibeAtividadesLocal.php?id=60","https://www.arqrio.com.br/curia/ajaxExibeAtividadesLocal.php?id=405","https://www.arqrio.com.br/curia/ajaxExibeAtividadesLocal.php?id=407","https://www.arqrio.com.br/curia/ajaxExibeAtividadesLocal.php?id=404","https://www.arqrio.com.br/curia/ajaxExibeAtividadesLocal.php?id=408","https://www.arqrio.com.br/curia/ajaxParoquiasRecuperarDetalhes.php?id=60"}', 'media'),
  ('11717fa1-8d2d-562d-b337-40f49922cb9f', 'Vicariato Episcopal Urbano, 2ª Forania. A matriz é santuário. Horários do cadastro da Cúria (sem data de atualização).', '{"https://www.arqrio.com.br/curia/ajaxExibeAtividadesLocal.php?id=76","https://www.arqrio.com.br/curia/ajaxExibeAtividadesLocal.php?id=437","https://www.arqrio.com.br/curia/ajaxExibeAtividadesLocal.php?id=438","https://www.arqrio.com.br/curia/ajaxExibeAtividadesLocal.php?id=441","https://www.arqrio.com.br/curia/ajaxParoquiasRecuperarDetalhes.php?id=76"}', 'media'),
  ('d682dd35-062c-510f-a211-b3d1a3861284', 'Vicariato Episcopal Urbano, 2ª Forania. Horários do cadastro da Cúria (sem data de atualização).', '{"https://www.arqrio.com.br/curia/ajaxExibeAtividadesLocal.php?id=273","https://www.arqrio.com.br/curia/ajaxParoquiasRecuperarDetalhes.php?id=273"}', 'media'),
  ('24106252-28dd-56af-8810-1cff53fd290c', 'Vicariato Episcopal Urbano, 2ª Forania. A matriz é santuário. Horários do cadastro da Cúria (sem data de atualização). Fora do formato: Quinta 08:30: Adoração ao Santíssimo Sacramento (ultima quinta-feira de cada mês)', '{"https://www.arqrio.com.br/curia/ajaxExibeAtividadesLocal.php?id=89","https://www.arqrio.com.br/curia/ajaxExibeAtividadesLocal.php?id=469","https://www.arqrio.com.br/curia/ajaxParoquiasRecuperarDetalhes.php?id=89"}', 'media'),
  ('e7619d03-941c-5eaa-925f-930a0ceafac1', 'Vicariato Episcopal Urbano, 1ª Forania. Horários do cadastro da Cúria (sem data de atualização).', '{"https://www.arqrio.com.br/curia/ajaxExibeAtividadesLocal.php?id=106","https://www.arqrio.com.br/curia/ajaxExibeAtividadesLocal.php?id=528","https://www.arqrio.com.br/curia/ajaxExibeAtividadesLocal.php?id=529","https://www.arqrio.com.br/curia/ajaxParoquiasRecuperarDetalhes.php?id=106"}', 'media'),
